// Every artifact is text. Injected backend, no NI, COM or real VI execution.
public static class ViMergeAcceptance {
    static readonly List<object> checks=new List<object>();static int serial;static string root;
    static void Check(string name,bool condition){checks.Add(new{name,passed=condition});if(!condition)throw new Exception(name);}
    static void Reject(string name,Action action){try{action();}catch(ArgumentException){Check(name,true);return;}catch(InvalidDataException){Check(name,true);return;}catch(IOException){Check(name,true);return;}catch(UnauthorizedAccessException){Check(name,true);return;}catch(InvalidOperationException){Check(name,true);return;}throw new Exception("Unexpected acceptance: "+name);}
    static string Put(string path,string text){if(!Path.GetFullPath(path).StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new Exception("Test escaped root");Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));return path;}
    static string Source(string name){string folder=Path.Combine(root,"projects",name+"_"+(++serial));string vi=Put(Path.Combine(folder,name+".vi"),"OFFLINE TEXT; NOT A VI");Put(Path.Combine(folder,"recipe.json"),Data.Json.Serialize(new{schema_version=1,name,steps=new object[0]}));Put(Path.Combine(folder,"recipe-report.json"),Data.Json.Serialize(new{created=true,vi_path=vi,vi_sha256=Data.Hash(vi),execution_state=1,static_checks_passed=true,steps=new object[0]}));return vi;}
    static string CopySource(string parent,string name,params string[] operations){string vi=Source(name);string folder=Path.GetDirectoryName(vi);var steps=operations.Select((op,i)=>new{id="op"+i,op,args=new{}}).ToArray();Put(Path.Combine(folder,"recipe.json"),Data.Json.Serialize(new{schema_version=1,name,source_vi=parent,steps}));string rp=Path.Combine(folder,"recipe-report.json");var report=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(rp)));report["steps"]=operations.Select((op,i)=>new{id="op"+i,operation=op}).ToArray();Put(rp,Data.Json.Serialize(report));Put(Path.Combine(folder,"source-copy-report.json"),Data.Json.Serialize(new{source=GeneratedViDependency.ValidateOne(parent).ToEvidence(),target_path=vi,source_file_unchanged=true,source_saved=false,source_executed=false}));return vi;}
    static string ImportSource(){string vi=Source("Imported");string rp=Path.Combine(Path.GetDirectoryName(vi),"recipe-report.json");var report=Data.Map(Data.Json.DeserializeObject(File.ReadAllText(rp)));report["artifact_kind"]="imported_vi";report["import_source"]=new{path=Path.Combine(root,"external","historical.vi"),before_sha256=new string('a',64),after_sha256=new string('a',64),unchanged=true};Put(rp,Data.Json.Serialize(report));return vi;}
    static Dictionary<string,object> Endpoint(string uid,Dictionary<string,object> owner,string diagram,bool source,string name){return new Dictionary<string,object>{{"uid",uid},{"owner",owner},{"diagram_uid",diagram},{"is_source",source},{"name",name},{"descriptor",new[]{4,10}}};}
    static Dictionary<string,object> Wire(string uid,params object[] terms){return new Dictionary<string,object>{{"uid",uid},{"terminals",terms}};}
    static Dictionary<string,object> Args(){return new Dictionary<string,object>{{"source_path",Source("Source")},{"target_source_path",Source("Target")},{"name","Merged"},{"filename","合并结果.vi"},{"dx",400},{"dy",0}};}
    static ViMerge.Request Request(){return ViMerge.Prepare(ViMerge.Parse(Args()));}
    static Dictionary<string,object> Row(string label,string uid){return new Dictionary<string,object>{{"label",label},{"uid",uid},{"class","Digital"},{"indicator",false},{"descriptor",new object[]{6,16395}},{"bounds",new object[]{10,20,30,40}},{"position",new[]{40,60}},{"value",0.0},{"value_clr_type","System.Double"},{"default_value",0.0},{"default_clr_type","System.Double"}};}
    // Synthetic descriptors use the root-name suffix observed in the actual
    // InputA/blank native receipt; these tests do not claim a new NI encoding.
    static int[] NamedTd(int[] core,string name){var words=core.ToList();words[1]=name.Length==0?words[1]&~0x4000:words[1]|0x4000;if(name.Length>0){var text=Encoding.ASCII.GetBytes(name);var suffix=new byte[(text.Length+2)/2*2];suffix[0]=(byte)text.Length;Array.Copy(text,0,suffix,1,text.Length);for(int i=0;i<suffix.Length;i+=2)words.Add(suffix[i]*256+suffix[i+1]);}words[0]=words.Count*2;return words.ToArray();}
    static Dictionary<string,object> NativeRow(string name,string uid,int[] core){var row=Row(name,uid);var td=NamedTd(core,name);row["descriptor"]=td;row["metadata_genericSchema"]=ViMerge.DescriptorSchema(td);return row;}
    static Dictionary<string,object> RenamedRow(Dictionary<string,object> old,string name,int[] core){var row=new Dictionary<string,object>(old);var td=NamedTd(core,name);row["label"]=name;row["descriptor"]=td;row["metadata_genericSchema"]=ViMerge.DescriptorSchema(td);return row;}
    static Dictionary<string,object> Obj(string uid,string kind,int x,int y){return new Dictionary<string,object>{{"uid",uid},{"class",kind},{"position",new[]{x,y}},{"bounds",new[]{32,32}}};}
    static Dictionary<string,object> Diagram(string uid,int depth,string parent,int frame,object[] objects,object[] wires){return new Dictionary<string,object>{{"uid",uid},{"depth",depth},{"parent_uid",parent},{"frame",frame},{"classes",objects.Select(Data.Map).Select(o=>Data.Text(o,"class")).OrderBy(x=>x,StringComparer.Ordinal).ToArray()},{"wire_count",wires.Length},{"objects",objects},{"wires",wires}};}
    sealed class Fake:ViMerge.Backend {
        internal ViMerge.Request Request;internal bool Merged;internal int Calls,Saves;internal string Alias,RejectedPath;internal string[] SavedCallees=new string[0];internal Action BeforeMerge;
