        public object Open(string path){Opens.Add(path);return path;}public string LoadedPath(object vi){return Alias!=null&&(string)vi==Request.Target?Alias:(string)vi;}public int State(object vi){return RejectedPath==(string)vi?0:1;}
        public string[] Callees(object vi){return Saves>0&&(string)vi==Request.Target?SavedCallees:new string[0];}
        public void Save(object vi,string path){if(path!=Request.Target)throw new Exception("Saved original");File.AppendAllText(path,"FAKE_SAVE");Saves++;}
        public Dictionary<string,object>[] Panel(string path){return path==Request.Scratch?SourcePanel:Merged?(AfterPanel==null?TargetPanel.Concat(SourcePanel.Select((row,i)=>{var copied=new Dictionary<string,object>(row);copied["uid"]=Convert.ToString(300+i);return copied;})).ToArray():AfterPanel()):TargetPanel;}
        public string RenameControl(string path,string uid,string newLabel){if(path!=Request.Scratch)throw new Exception("Renamed original or target");SourcePanel=SourcePanel.Select(row=>{var copied=new Dictionary<string,object>(row);if(Data.Text(row,"uid")==uid)copied["label"]=newLabel;return copied;}).ToArray();return uid;}
        public object[] Diagrams(string path){if(path==Request.Target&&Merged&&AfterDiagrams!=null)return AfterDiagrams();var originals=TargetPanel.Select((row,i)=>(object)Obj(Data.Text(row,"uid"),"ControlTerminal",30+i*100,30));var copies=SourcePanel.Select((row,i)=>(object)Obj(Convert.ToString(300+i),"ControlTerminal",50+i*100+Request.Dx,50+Request.Dy));return new object[]{Diagram(path==Request.Scratch?"source_diagram":"target_diagram",0,"",0,path==Request.Scratch?SourcePanel.Select((row,i)=>(object)Obj(Data.Text(row,"uid"),"ControlTerminal",50+i*100,50)).ToArray():Merged?originals.Concat(copies).ToArray():originals.ToArray(),new object[0])};}
        public object Connector(string path){return new{pattern=ChangedConnector&&Merged&&path==Request.Target?999:4800,terminal_count=4,control_uids=new[]{"","","",""}};}
        public int Merge(string source,string target,int dx,int dy){if(BeforeMerge!=null)BeforeMerge();Calls++;if(source!=Request.Scratch||target!=Request.Target)throw new Exception("Wrong mutation targets");Merged=true;return 1;}
        public void Dispose(){}
    }
    static Fake Backend(ViMerge.Request r){return new Fake{Request=r};}
